     5	public class ClaimOffice {
     6	
     7	    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
     8	    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = Modifier.rate(10);
     9	    private static final BigDecimal LOYALTY_DISCOUNT_RATE = Modifier.rate(20);
    10	    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = Modifier.rate(15);
    11	
    12	    /** From this many years of business on, the MHPCO calls a customer long-standing. */
    13	    private static final int LONG_STANDING_YEARS = 2;
    14	
    15	    private final Customer customer;
    16	    private final ContractHistory contractHistory = new ContractHistory();
    17	
    18	    public ClaimOffice(Customer customer) {
    19	        this.customer = customer;
    20	    }
    21	
    22	    /**
    23	     * The office quotes the premium for the items and, in doing so, writes the
    24	     * contract: the premium is priced against the customer's file as it stands, and
    25	     * only then does the new contract enter that file.
    26	     */
    27	    public int quote(List<Item> items) {
    28	        int premium = premiumFor(items);
    29	        contractHistory.recordContractWritten();
    30	        return premium;
    31	    }
    32	
    33	    /** The office writes a policy for the items, charging the quoted premium. */
    34	    public Policy insure(List<Item> items) {
    35	        return new Policy(items, quote(items));
    36	    }
    37	
    38	    /** The office settles a claim reported against one of its policies. */
    39	    public Settlement claim(Policy policy, Incident incident) {
    40	        return ClaimSettlement.forIncident(policy, incident);
    41	    }
    42	
    43	    /** What the office charges for these items: every scope's contribution, plus the fee. */
    44	    private int premiumFor(List<Item> items) {
    45	        BigDecimal policyBasePremium = PolicyBasePremium.of(items);
    46	        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
    47	                .add(ItemRiskRating.surchargesFor(items));
    48	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
    49	    }
    50	
    51	    /**
    52	     * What the policy scope contributes: the policy base premium itself, adjusted by
    53	     * the modifiers the office applies to the policy as a whole.
    54	     */
    55	    private BigDecimal policyScopeContribution(BigDecimal policyBasePremium) {
    56	        BigDecimal contribution = policyBasePremium
    57	                .add(policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE));
    58	        if (isLongStanding()) {
    59	            contribution = contribution
    60	                    .subtract(policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE));
    61	        }
    62	        if (contractHistory.nextContractIsFollowUp()) {
    63	            contribution = contribution
    64	                    .subtract(policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE));
    65	        }
    66	        return contribution;
    67	    }
    68	
    69	    /** Two years of business with the MHPCO make a customer long-standing. */
    70	    private boolean isLongStanding() {
    71	        return customer.yearsWithMHPCO() >= LONG_STANDING_YEARS;
    72	    }
    73	
    74	    /**
    75	     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
    76	     * amounts stay exact fractions, so only this final step loses the remainder.
    77	     */
    78	    private static int roundInOfficeFavour(BigDecimal premium) {
    79	        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    80	    }
    81	}
