     2	import java.math.RoundingMode;
     3	
     4	/**
     5	 * How the MHPCO settles damage reported against a policy: it resolves each reported
     6	 * damage to the insured item it names, asks its reimbursement clauses how much of
     7	 * that damage it recognises, withholds the deductible per damage event, and pays out
     8	 * the total.
     9	 *
    10	 * <p>Separate from what the office charges: a premium is priced from the price list,
    11	 * the customer's file and the item's risk, while a payout is decided from the damage
    12	 * and the damaged item alone. The two change for different reasons -- so much so that
    13	 * the office's own favour points in opposite directions, rounding a premium up but a
    14	 * payout down.
    15	 */
    16	public final class ClaimSettlement {
    17	
    18	    /** The MHPCO keeps this much of every damage event to itself. */
    19	    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = BigDecimal.valueOf(100);
    20	
    21	    private ClaimSettlement() {
    22	    }
    23	
    24	    /** What the office pays out for everything the incident damaged. */
    25	    public static Settlement forIncident(Policy policy, Incident incident) {
    26	        BigDecimal payout = incident.damages().stream()
    27	                .map(damage -> reimbursementFor(damage, damagedItem(policy, damage)))
    28	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    29	        int paid = policy.drawAgainstCap(roundInOfficeFavour(payout));
    30	        return new Settlement(paid, policy.remainingCap());
    31	    }
    32	
    33	    /**
    34	     * The insured item a reported damage names. The office matches a damage to the
    35	     * first insured item of that type.
    36	     *
    37	     * <p>Deliberately incomplete: the specification rejects a claim whose damage
    38	     * names an item the policy does not cover, and equally a claim reporting more
    39	     * damages of a type than the policy insures -- which this lookup would instead
    40	     * resolve to the same item twice. Neither rejection is implemented yet, so an
    41	     * uncovered type surfaces only as a bare lookup failure.
    42	     */
    43	    private static Item damagedItem(Policy policy, Damage damage) {
    44	        return policy.items().stream()
    45	                .filter(item -> item.type().equals(damage.itemType()))
    46	                .findFirst()
    47	                .orElseThrow();
    48	    }
    49	
    50	    /** What the office reimburses for one damaged item, after its deductible. */
    51	    private static BigDecimal reimbursementFor(Damage damage, Item item) {
    52	        return ReimbursementClause.recognisedAmountOf(damage, item)
    53	                .subtract(DEDUCTIBLE_PER_DAMAGE);
    54	    }
    55	
    56	    /**
    57	     * A payout is rounded down: the MHPCO rounds in its own favour. Intermediate
    58	     * amounts stay exact fractions, so only this final step loses the remainder.
    59	     */
    60	    private static int roundInOfficeFavour(BigDecimal payout) {
    61	        return payout.setScale(0, RoundingMode.FLOOR).intValueExact();
    62	    }
    63	}
