     4	/**
     5	 * How the MHPCO rates the risk an individual item carries. A risky trait costs a
     6	 * surcharge on that item's own base premium, never on the policy total -- the office
     7	 * charges for the risk it takes on the item, not for the company the item keeps.
     8	 */
     9	public final class ItemRiskRating {
    10	
    11	    private static final BigDecimal CURSE_SURCHARGE_RATE = Modifier.rate(50);
    12	    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = Modifier.rate(30);
    13	
    14	    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
    15	    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    16	
    17	    private ItemRiskRating() {
    18	    }
    19	
    20	    /** The risk surcharges every item in the policy contributes, added up. */
    21	    public static BigDecimal surchargesFor(List<Item> items) {
    22	        return items.stream()
    23	                .map(ItemRiskRating::surchargeFor)
    24	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    25	    }
    26	
    27	    /** What this item's own risky traits add to the premium. */
    28	    private static BigDecimal surchargeFor(Item item) {
    29	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
    30	        BigDecimal surcharge = BigDecimal.ZERO;
    31	        if (item.cursed()) {
    32	            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
    33	        }
    34	        if (isHighlyEnchanted(item)) {
    35	            surcharge = surcharge.add(
    36	                    itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
    37	        }
    38	        return surcharge;
    39	    }
    40	
    41	    private static boolean isHighlyEnchanted(Item item) {
    42	        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    43	    }
    44	}
