     1	import java.util.List;
     2	
     3	/**
     4	 * A contract the MHPCO has written: the items it covers, the premium charged, and
     5	 * how much of its payout cap is still available.
     6	 */
     7	public final class Policy {
     8	
     9	    /** The office never pays out more than this multiple of the insurance sum. */
    10	    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    11	
    12	    private final List<Item> items;
    13	    private final int premium;
    14	    private int remainingCap;
    15	
    16	    public Policy(List<Item> items, int premium) {
    17	        this.items = List.copyOf(items);
    18	        this.premium = premium;
    19	        this.remainingCap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
    20	    }
    21	
    22	    public List<Item> items() {
    23	        return items;
    24	    }
    25	
    26	    public int premium() {
    27	        return premium;
    28	    }
    29	
    30	    /** What remains of the total the office will pay out over this policy's life. */
    31	    public int remainingCap() {
    32	        return remainingCap;
    33	    }
    34	
    35	    /**
    36	     * The office draws a settled payout against the policy's cap and pays out what
    37	     * the cap still allows: a desired payout beyond the remaining cap is reduced to
    38	     * it. The cap is the policy's own ledger -- only the policy knows how much of it
    39	     * earlier claims have already spent.
    40	     */
    41	    int drawAgainstCap(int desiredPayout) {
    42	        int paid = Math.min(desiredPayout, remainingCap);
    43	        remainingCap -= paid;
    44	        return paid;
    45	    }
    46	
    47	    /** What the policy insures in total: the sum of its items' insurance values. */
    48	    private int insuranceSum() {
    49	        return items.stream().mapToInt(MhpcoPriceList::insuranceValueOf).sum();
    50	    }
    51	}
=== PolicyBasePremium.java ===
     1	import java.math.BigDecimal;
     2	import java.util.List;
     3	import java.util.Map;
     4	import java.util.stream.Collectors;
     5	
     6	/**
     7	 * What the office charges for a policy's items before any modifier: every main item
     8	 * at its price-list premium, and each group of alike components priced together, so
     9	 * that the MHPCO's building-block offer can be recognised.
    10	 *
    11	 * <p>The block is an offer on the premium alone. It deliberately says nothing about
    12	 * what the office insures those components for.
    13	 */
    14	public final class PolicyBasePremium {
    15	
    16	    /** A building block of exactly 3 alike components is offered at a special price. */
    17	    private static final int COMPONENT_BLOCK_SIZE = 3;
    18	    private static final int COMPONENT_BLOCK_BASE_PREMIUM = 60;
    19	
    20	    private PolicyBasePremium() {
    21	    }
    22	
    23	    public static BigDecimal of(List<Item> items) {
    24	        BigDecimal mainItems = items.stream()
    25	                .filter(item -> !MhpcoPriceList.isComponent(item))
    26	                .map(MhpcoPriceList::basePremiumOf)
    27	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    28	        BigDecimal components = alikeComponentCounts(items).values().stream()
    29	                .map(PolicyBasePremium::alikeComponentsBasePremiumOf)
    30	                .reduce(BigDecimal.ZERO, BigDecimal::add);
    31	        return mainItems.add(components);
    32	    }
    33	
    34	    /** How many components of each type the policy covers, grouped by their type. */
    35	    private static Map<String, Long> alikeComponentCounts(List<Item> items) {
    36	        return items.stream()
    37	                .filter(MhpcoPriceList::isComponent)
    38	                .collect(Collectors.groupingBy(Item::type, Collectors.counting()));
    39	    }
    40	
    41	    /**
    42	     * What the office charges for the alike components of one type: a building block
    43	     * is offered at its special price, anything else is priced component by component.
    44	     */
    45	    private static BigDecimal alikeComponentsBasePremiumOf(long alikeCount) {
    46	        if (formsBuildingBlock(alikeCount)) {
    47	            return BigDecimal.valueOf(COMPONENT_BLOCK_BASE_PREMIUM);
    48	        }
    49	        return BigDecimal.valueOf(alikeCount * MhpcoPriceList.COMPONENT_BASE_PREMIUM);
    50	    }
    51	
    52	    /** The block price is offered for exactly 3 alike components -- no more, no less. */
    53	    private static boolean formsBuildingBlock(long alikeCount) {
    54	        return alikeCount == COMPONENT_BLOCK_SIZE;
    55	    }
    56	}
=== ReimbursementClause.java ===
     1	import java.math.BigDecimal;
     2	
     3	/**
     4	 * The MHPCO's clauses on how much of a reported damage it recognises at all, before
     5	 * the deductible is withheld. A clause looks only at the damaged item and the amount
     6	 * claimed: it is the office's statement about the risk the item carried, not about
     7	 * the customer, the contract or the price list.
     8	 *
     9	 * <p>The office knows two clauses, and reads them in this order of precedence:
    10	 *
    11	 * <ol>
    12	 *   <li>Damage to a highly enchanted item (enchantment level &gt;= 8) is recognised
    13	 *       at half. This clause wins wherever it applies.</li>
    14	 *   <li>Damage to an item of dragon material is recognised in full.</li>
    15	 * </ol>
    16	 *
    17	 * <p>Only the first clause is encoded below, and deliberately so. Full recognition is
    18	 * already the office's default for every damage no clause touches, so the dragon-material
    19	 * clause prescribes exactly what would happen without it: it is stated by the tariff but
    20	 * changes no amount. Encoding it would mean a branch returning the same figure as the
    21	 * fall-through, which no claim could ever tell apart -- the office would be unable to
    22	 * check the clause it had written down. The clause is therefore recorded here rather
    23	 * than in code, and {@link Item#material()} accordingly bears on no payout today. Should
    24	 * the office ever lower its default recognition below full, this clause becomes
    25	 * observable and earns its branch, immediately above the default.
    26	 *
    27	 * <p>The recognised amount stays an exact fraction -- a halved damage of an odd amount is
    28	 * genuinely a half-G, and the MHPCO's rounding belongs to the final payout alone.
    29	 */
    30	public final class ReimbursementClause {
    31	
    32	    /** From this enchantment level on, the office recognises only half a damage. */
    33	    private static final int HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
    34	
    35	    private static final BigDecimal HALF = BigDecimal.valueOf(5, 1);
    36	
    37	    private ReimbursementClause() {
    38	    }
    39	
    40	    /** How much of this damage to this item the office recognises. */
    41	    public static BigDecimal recognisedAmountOf(Damage damage, Item item) {
    42	        BigDecimal claimed = BigDecimal.valueOf(damage.amount());
    43	        if (isHighlyEnchanted(item)) {
    44	            return claimed.multiply(HALF);
    45	        }
    46	        return claimed;
    47	    }
    48	
    49	    /** Whether the halving clause reaches this item at all. */
    50	    private static boolean isHighlyEnchanted(Item item) {
    51	        return item.enchantment() >= HALVED_REIMBURSEMENT_ENCHANTMENT;
    52	    }
    53	}
