import java.util.List;

/**
 * A contract the MHPCO has written: the items it covers, the premium charged, and
 * how much of its payout cap is still available.
 */
public final class Policy {

    /** The office never pays out more than this multiple of the insurance sum. */
    private static final int CAP_MULTIPLE_OF_INSURANCE_SUM = 2;

    private final List<Item> items;
    private final int premium;
    private int remainingCap;

    public Policy(List<Item> items, int premium) {
        this.items = List.copyOf(items);
        this.premium = premium;
        this.remainingCap = CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSum();
    }

    /**
     * The insured item a reported damage names. The office matches a damage to the
     * first covered item of that type: what the policy covers is the policy's own
     * knowledge, so the policy answers the question rather than handing out its items.
     *
     * <p>Deliberately incomplete: the specification rejects a claim whose damage names
     * an item the policy does not cover, and equally a claim reporting more damages of
     * a type than the policy insures -- which this lookup would instead resolve to the
     * same item twice. Neither rejection is implemented yet, so an uncovered type
     * surfaces only as a bare lookup failure. Both are decisions about what this policy
     * covers, and belong here when they come.
     */
    Item insuredItemFor(Damage damage) {
        return items.stream()
                .filter(item -> item.type().equals(damage.itemType()))
                .findFirst()
                .orElseThrow();
    }
